//! The `libghostty-vt` C ABI, as Rust sees it.
//!
//! The bindings are generated by `build.rs` from the headers that ship next to
//! the library. Nothing is declared by hand: a `#[repr(C)]` struct that is right
//! until the first upstream field moves is a struct nobody can trust.
//!
//! This module is the only place that knows the engine exists. Everything above
//! it works with the crate's own names, so a signature change upstream is one
//! compile error here rather than a mystery at every call site.
//!
//! ## The re-exports
//!
//! bindgen emits a C enum as a set of constants named `<EnumType>_<VARIANT>`,
//! with the enum type itself an integer alias. The aliases below put every
//! variant back under the name the header uses, so the code reads like the API
//! it calls — and a variant that disappears upstream is a compile error here
//! rather than a number that quietly changed meaning.

#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]

include!(concat!(env!("OUT_DIR"), "/ghostty.rs"));

/// The engine's success code.
///
/// A `#define` in the header; written out because it is the one value every
/// call is compared against and a missing name there would be a missing
/// constant at forty call sites.
pub const SUCCESS: GhosttyResult = 0;

/// The engine's "no value" answer: the call succeeded and there was nothing
/// to return.
pub const NO_VALUE: GhosttyResult = -4;

/// True when a call succeeded.
pub fn ok(result: GhosttyResult) -> bool {
    result == SUCCESS
}

